import { MakeLogicType, actions, kea, listeners, path, reducers, selectors } from 'kea'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todaySceneTabsLogicValues {
    held: boolean
    mountedCount: number
    sceneTabsMounted: boolean
    tabsElement: HTMLElement | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todaySceneTabsLogicActions {
    addSceneTabs: () => {
        value: true
    }
    registerTabsElement: (element: HTMLElement | null) => {
        element: HTMLElement | null
    }
    releaseSceneTabs: () => {
        value: true
    }
    removeSceneTabs: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todaySceneTabsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        sceneTabsMounted: (mountedCount: number, held: boolean) => boolean
    }
}

export type todaySceneTabsLogicType = MakeLogicType<
    todaySceneTabsLogicValues,
    todaySceneTabsLogicActions,
    Record<string, any>,
    todaySceneTabsLogicMeta
>

// How long the sidebar outlives its last tab bar, so a page swap that remounts the tabs does not collapse it.
export const SCENE_TABS_RELEASE_DELAY_MS = 300

export const todaySceneTabsLogic = kea<todaySceneTabsLogicType>([
    path(['layout', 'today', 'todaySceneTabsLogic']),
    actions({
        registerTabsElement: (element: HTMLElement | null) => ({ element }),
        addSceneTabs: true,
        removeSceneTabs: true,
        releaseSceneTabs: true,
    }),
    reducers({
        held: [
            false,
            {
                addSceneTabs: () => false,
                removeSceneTabs: () => true,
                releaseSceneTabs: () => false,
            },
        ],
        tabsElement: [
            null as HTMLElement | null,
            {
                registerTabsElement: (_, { element }) => element,
            },
        ],
        mountedCount: [
            0,
            {
                addSceneTabs: (state) => state + 1,
                removeSceneTabs: (state) => Math.max(0, state - 1),
            },
        ],
    }),
    selectors({
        sceneTabsMounted: [
            (s) => [s.mountedCount, s.held],
            (mountedCount: number, held: boolean): boolean => mountedCount > 0 || held,
        ],
    }),
    listeners(({ actions, values, cache }) => ({
        addSceneTabs: () => {
            cache.disposables.dispose('release')
        },
        removeSceneTabs: () => {
            if (values.mountedCount > 0) {
                return
            }
            cache.disposables.add(() => {
                const timeout = setTimeout(() => actions.releaseSceneTabs(), SCENE_TABS_RELEASE_DELAY_MS)
                return () => clearTimeout(timeout)
            }, 'release')
        },
    })),
])
